import{_ as o,o as a,c as p,a2 as t}from"./chunks/framework.CqGPl1zp.js";const r="/newx-doc/assets/%E6%B5%8B%E8%AF%95%E5%85%AC%E4%BC%97%E5%8F%B7-%E5%AF%86%E9%92%A5.wPtQ5QBS.png",c="/newx-doc/assets/%E5%90%8E%E7%AB%AF%E9%85%8D%E7%BD%AE%E9%A1%B9.qAJAajqH.png",i="/newx-doc/assets/JS%E6%8E%A5%E5%8F%A3%E5%AE%89%E5%85%A8%E5%9F%9F%E5%90%8D.eCRb5ppP.png",s="/newx-doc/assets/%E7%BD%91%E9%A1%B5%E6%8E%88%E6%9D%83%E8%8E%B7%E5%8F%96%E7%94%A8%E6%88%B7%E5%9F%BA%E6%9C%AC%E4%BF%A1%E6%81%AF.BJeJCIcN.png",n="/newx-doc/assets/IP%E7%99%BD%E5%90%8D%E5%8D%95.DfolX2CP.png",d="/newx-doc/assets/%E5%85%AC%E4%BC%97%E5%8F%B7%E8%AE%BE%E7%BD%AE.CQjqFACI.png",l="/newx-doc/assets/%E5%85%AC%E4%BC%97%E5%8F%B7%E7%BD%91%E9%A1%B5%E9%A1%B9%E7%9B%AE.D523vCLJ.png",E="/newx-doc/assets/%E7%99%BB%E5%BD%95%E5%BC%B9%E7%AA%97.DlXqgJn_.png",h="/newx-doc/assets/%E5%BE%AE%E4%BF%A1%E5%85%AC%E4%BC%97%E5%8F%B7%E7%9A%84%E7%99%BB%E5%BD%95%E5%9C%B0%E5%9D%80.lY9aZ46u.png",b=JSON.parse('{"title":"微信公众号登录","description":"","frontmatter":{},"headers":[],"relativePath":"member/weixin-mp-login.md","filePath":"member/weixin-mp-login.md","lastUpdated":null}'),m={name:"member/weixin-mp-login.md"};function _(u,e,g,A,f,B){return a(),p("div",null,[...e[0]||(e[0]=[t('<h1 id="微信公众号登录" tabindex="-1">微信公众号登录 <a class="header-anchor" href="#微信公众号登录" aria-label="Permalink to &quot;微信公众号登录&quot;">​</a></h1><p>前置阅读文章：</p><ul><li><a href="./../user-center">《用户体系》</a></li><li><a href="./../social-user">《三方登录》</a></li></ul><p>本文是 <a href="./../social-user">《三方登录》</a> 的延伸，讲解 <a href="https://github.com/yudaocode/yudao-mall-uniapp" target="_blank" rel="noreferrer"><code>yudao-mall-uniapp</code></a> 商城小程序如何实现微信 <strong>公众号</strong> 登录的功能。</p><h2 id="_1-公众号准备" tabindex="-1">1. 公众号准备 <a class="header-anchor" href="#_1-公众号准备" aria-label="Permalink to &quot;1. 公众号准备&quot;">​</a></h2><p>友情提示：</p><p>本文，我们以“测试公众号”举例子，方便大家操作，认证一个公众号太难了！！！</p><p>① 参考 <a href="https://mp.weixin.qq.com/debug/cgi-bin/sandbox?t=sandbox/login" target="_blank" rel="noreferrer">微信公众平台接口测试帐号申请</a> 链接，申请一个测试公众号。</p><p>② 将 <code>appID</code> 和 <code>appSecret</code> 配置，设置到后端项目 <code>application-local.yaml</code> 的 <code>wx.mp</code> 配置项中。如下图所示：</p><p><img src="'+r+'" alt="测试公众号 - 密钥"></p><p><img src="'+c+'" alt=" 配置项"></p><p>③ 修改“JS接口安全域名”，设置为前端的访问地址。例如说，现在本地是 <code>http://127.0.0.1:3000</code>。如下图所示：</p><p><img src="'+i+'" alt="JS 接口安全域名.png"></p><p>注意：自己需要关注下自己的测试公众号！！！</p><p>④ 修改“网页授权获取用户基本信息”，设置为前端的访问地址。例如说，现在本地是 <code>http://127.0.0.1:3000</code>。如下图所示：</p><p><img src="'+s+'" alt="网页授权获取用户基本信息"></p><p>补充说明：如果你是正式的公众号，需要额外看下这部分的内容：</p><p>① 设置“IP白名单”，在公众号的 [设置与开发 - 安全中心] 菜单，如下图所示：</p><p><img src="'+n+'" alt="IP 白名单"></p><p>② 在公众号的 [设置与开发 - 公众号设置] 菜单，设置“业务域名”、“JS接口安全域名”、“网页授权域名”，如下图所示：</p><p><img src="'+d+'" alt="公众号设置"></p><ul><li>设置时，需要外网可访问，可以需要使用 <a href="./../natapp">natapp</a> 进行内网穿透</li><li>上图的 <code>MP_verify_XXXXXXXXXXXXXXXX.txt</code> 文件，可以直接放在 <code>yudao-mall-uniapp</code> 商城项目的根目录</li></ul><h2 id="_2-代码实现" tabindex="-1">2. 代码实现 <a class="header-anchor" href="#_2-代码实现" aria-label="Permalink to &quot;2. 代码实现&quot;">​</a></h2><h3 id="_2-1-项目启动" tabindex="-1">2.1 项目启动 <a class="header-anchor" href="#_2-1-项目启动" aria-label="Permalink to &quot;2.1 项目启动&quot;">​</a></h3><p>① 参考 <a href="./../quick-start-front">《快速启动【前端】》</a> 文档的「2. uni-app 商城移动端」小节，将 <code>yudao-mall-uniapp</code> 商城项目跑起来。</p><p>② 下载 <a href="https://developers.weixin.qq.com/miniprogram/dev/devtools/download.html" target="_blank" rel="noreferrer">微信开发者工具</a> ，并进行安装。安装后，选择「公众号网页项目」。如下图所示：</p><p><img src="'+l+'" alt="公众号网页项目"></p><h3 id="_2-2-微信-jssdk" tabindex="-1">2.2 微信 JSSDK <a class="header-anchor" href="#_2-2-微信-jssdk" aria-label="Permalink to &quot;2.2 微信 JSSDK&quot;">​</a></h3><p>访问 <code>http://127.0.0.1:3000/</code> 地址（其它地址也可以），它会触发 <a href="https://developers.weixin.qq.com/doc/offiaccount/OA_Web_Apps/JS-SDK.html" target="_blank" rel="noreferrer">微信 JSSDK</a> 初始化的逻辑，对应前端 <code>sheep/libs/sdk-h5-weixin.js</code> 文件的 <code>#init(...)</code> 方法中。</p><p>微信 JSSDK 所需要的签名，由后端的 AppAuthController 的 <code>#createWeixinMpJsapiSignature(...)</code> 方法所提供。</p><p>友情提示：为什么出现微信 JSSDK 初始化失败：<code>{errMsg: &quot;config:fail,invalid signature&quot;}</code>？</p><p>可能是 <code>jsApiList</code> 里的部分权限你没有，可以尝试先全部移除，只保留 <code>chooseWXPay</code> 一个，确保初始化成功。</p><p>然后，再逐个添加 <code>jsApiList</code> 里的权限，找到所有权限都可以正常使用的 <code>jsApiList</code> 列表。</p><p>友情提示：为什么微信公众号 H5 在手机上分享功能不生效？</p><h3 id="_2-3-登录流程" tabindex="-1">2.3 登录流程 <a class="header-anchor" href="#_2-3-登录流程" aria-label="Permalink to &quot;2.3 登录流程&quot;">​</a></h3><p>友情提示：</p><p>可以简单阅读下 <a href="https://developers.weixin.qq.com/doc/offiaccount/OA_Web_Apps/Wechat_webpage_authorization.html" target="_blank" rel="noreferrer">《微信官方文档 —— 网页授权》</a> 文章。</p><p>① 访问 <code>http://127.0.0.1:3000/#/pages/user/info</code> 地址，触发弹出“登录窗口”，对应前端 <code>sheep/components/s-auth-modal/s-auth-modal.vue</code> 组件。如下图所示：</p><p><img src="'+E+'" alt="登录弹窗"></p><p>② 点击「微信登录」图标，触发微信公众号登录。前端核心实现都在 <code>sheep/platform/provider/wechat/officialAccount.js</code> 的 <code>#login(...)</code> 方法中。它一共包含 2 个步骤。</p><p>③ 【第一步】前端调用后端的 AppAuthController 的 <code>#socialAuthRedirect(...)</code> 方法，获得微信公众号的登录地址，并进行跳转。效果如下图：</p><p><img src="'+h+'" alt="微信公众号的登录地址"></p><p>ps：为了在微信登录成功后，可以回到登陆前的 URL 地址，会将该 URL 存储到 <code>uni.setStorageSync(&#39;returnUrl&#39;, location.href)</code> 中。</p><p>④ 【第二步】点击「同意」按钮，跳转回前端的 <code>pages/index/login.vue</code> 页面，进行 <strong>真正的</strong> 微信登录逻辑。</p><p>此时，前端从 URL 中解析到微信回调提供的 <code>code</code> 授权码参数，调用后端的 AppAuthController 的 <code>#socialLogin(...)</code> 方法，进行登录逻辑。注意：</p><ul><li>情况一：如果该微信用户已经绑定会员用户，则直接进行登录</li><li>情况二：如果该微信用户没有绑定会员用户，则会自动创建一个会员用户，并进行登录。下次重新登录时，就走【情况一】的逻辑。</li></ul><p>ps：登录成功后，通过 <code>uni.getStorageSync(&#39;returnUrl&#39;)</code> 获得登录前的 URL 地址，进行跳转。</p>',47)])])}const S=o(m,[["render",_]]);export{b as __pageData,S as default};
